import Authorization from "../user/auth.service";

const base_url = "marketplace-user-item";
const MarketplaceUserItemService = {
  // ============ LISTADOS ============

  async getList(filters = {}) {
    try {
      const search_data = { auth: "bearer", ...filters };
      const { status, data } = await Authorization.checkLogin(`/${base_url}`, search_data, "post");
      if (status === 200) {
        const list = [];
        for (let item of data) {
          list.push(this.transformItem(item));
        }
        return list;
      }
    } catch (e) {
      console.error(e);
      return [];
    }
  },

  getSimpleList() {
    return this.getList().then((list) => {
      return list.map((l) => ({
        value: l.id,
        text: l.product || l.user_email || "[Sin nombre]",
      }));
    });
  },

  async getById(id) {
    try {
      const { status, data } = await Authorization.checkLogin(`/${base_url}/${id}`, { auth: "bearer" });
      if (status === 200) return data;
    } catch (e) {
      console.error(e.response);
    }
  },

  // ============ CRUD ============

  async addUpdMarketplaceUserItem(form_data) {
    try {
      form_data.auth = "bearer";
      const url = `/${base_url}/upsert`;
      const method = "post";

      const { status, data } = await Authorization.checkLogin(url, form_data, method);

      if (status === 200) return data;
    } catch (e) {
      console.error(e.response);
    }
    return false;
  },

  async delete(ids) {
    const delete_data = { auth: "bearer", ids };
    try {
      const { status, data } = await Authorization.checkLogin(`/${base_url}/delete`, delete_data, "post");
      if (status === 200) {
        return this.getList();
      }
    } catch (e) {
      console.error(e.response);
    }
  },

  // ============ FAST UPDATE ============

  async fastUpdate(id, field, value) {
    try {
      let column = field;
      // Mapear campos frontend -> backend si es necesario

      const form_data = { auth: "bearer", [column]: value };
      const { status, data } = await Authorization.checkLogin(`/${base_url}/fast-upd/${id}`, form_data, "put");
      if (status === 200) return data;
    } catch (e) {
      console.error(e.response);
    }
    return false;
  },

  // ============ BÚSQUEDA Y EXPORTACIÓN ============

  async search(filters = {}) {
    try {
      const search_data = { auth: "bearer", ...filters };
      const { status, data } = await Authorization.checkLogin(`/${base_url}/search-backend`, search_data, "post");
      if (status === 200) {
        const list = [];
        for (let item of data) {
          list.push(this.transformItem(item));
        }
        return list;
      }
    } catch (e) {
      console.error(e.response);
      return [];
    }
  },

  async searchAndExport(filters = {}, limit = null, offset = 0) {
    try {
      const search_data = { auth: "bearer", ...filters };
      if (limit !== null) search_data.limit = limit;
      if (offset > 0) search_data.offset = offset;

      const { status, data } = await Authorization.checkLogin(`/${base_url}/search-backend`, search_data, "post");
      if (status === 200) {
        const list = [];
        for (let item of data) {
          list.push({
            ...this.transformItem(item),
            description: item.description || "",
            created_at: item.created_at,
            updated_at: item.updated_at,
          });
        }
        return list;
      }
    } catch (e) {
      console.error(e.response);
      return [];
    }
  },

  async getCount(filters = {}) {
    try {
      const search_data = {
        auth: "bearer",
        ...filters,
        count_only: true,
      };
      const { status, data } = await Authorization.checkLogin(`/${base_url}/search-backend`, search_data, "post");
      if (status === 200) return data.count || data;
      return 0;
    } catch (e) {
      console.error(e.response);
      return 0;
    }
  },

  // ============ TRANSFORMACIÓN ============

  transformItem(item) {
    return {
      id: item.id,
      product: item.item?.alias || item.product || "",
      user_email: item.user?.email || item.user_email || "",
      discount: item.discount || 0,
      description: item.description || "",
      active: item.active ? true : false,
      is_percent: item.is_percent ? true : false,
    };
  },
};

export default MarketplaceUserItemService;
