<!-- components/marketplace/MarketplaceReportStatics.vue -->
<template>
    <div class="marketplace-report-results">
        <!-- Header del Reporte -->
        <div class="flex items-center justify-between mb-6">
            <h2 class="text-2xl font-bold text-gray-800">📊 Reporte de Ventas</h2>
            <div class="flex gap-2">
                <StaticsPDFReport 
                    :reportData="reportData" 
                    :filters="filters"
                    :filename="`reporte-ventas-${currentDate}.pdf`"
                />
                <StaticsExcelReport 
                    :reportData="reportData" 
                    :filters="filters"
                    :filename="`reporte-ventas-${currentDate}.xlsx`"
                />
            </div>
        </div>

        <!-- Tarjetas de Resumen General -->
        <div class="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
            <div class="bg-gradient-to-br from-blue-500 to-blue-600 rounded-lg shadow-lg p-4 text-white">
                <div class="text-sm opacity-90">Ventas Totales</div>
                <div class="text-2xl font-bold">${{ formatCurrency(reportData.generalTotal.totalSales) }}</div>
                <div class="text-xs opacity-75 mt-1">Total general</div>
            </div>
            
            <div class="bg-gradient-to-br from-green-500 to-green-600 rounded-lg shadow-lg p-4 text-white">
                <div class="text-sm opacity-90">Órdenes</div>
                <div class="text-2xl font-bold">{{ totalOrders }}</div>
                <div class="text-xs opacity-75 mt-1">En todos los estados</div>
            </div>
            
            <div class="bg-gradient-to-br from-purple-500 to-purple-600 rounded-lg shadow-lg p-4 text-white">
                <div class="text-sm opacity-90">Productos</div>
                <div class="text-2xl font-bold">{{ totalUniqueProducts }}</div>
                <div class="text-xs opacity-75 mt-1">Productos diferentes</div>
            </div>
            
            <div class="bg-gradient-to-br from-yellow-500 to-yellow-600 rounded-lg shadow-lg p-4 text-white">
                <div class="text-sm opacity-90">Categorías</div>
                <div class="text-2xl font-bold">{{ totalCategories }}</div>
                <div class="text-xs opacity-75 mt-1">Categorías con ventas</div>
            </div>
        </div>

        <!-- Tabs de navegación -->
        <div class="border-b border-gray-200 mb-4">
            <nav class="flex -mb-px">
                <button @click="activeTab = 'general'" 
                    :class="['mr-8 py-2 px-1 border-b-2 font-medium text-sm transition',
                        activeTab === 'general' 
                            ? 'border-blue-500 text-blue-600' 
                            : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300']">
                    <i class="fas fa-chart-pie mr-2"></i>Vista General
                </button>
                <button @click="activeTab = 'byStatus'" 
                    :class="['mr-8 py-2 px-1 border-b-2 font-medium text-sm transition',
                        activeTab === 'byStatus' 
                            ? 'border-blue-500 text-blue-600' 
                            : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300']">
                    <i class="fas fa-tags mr-2"></i>Por Estado
                </button>
                <button @click="activeTab = 'products'" 
                    :class="['mr-8 py-2 px-1 border-b-2 font-medium text-sm transition',
                        activeTab === 'products' 
                            ? 'border-blue-500 text-blue-600' 
                            : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300']">
                    <i class="fas fa-box mr-2"></i>Productos
                </button>
                <button @click="activeTab = 'categories'" 
                    :class="['mr-8 py-2 px-1 border-b-2 font-medium text-sm transition',
                        activeTab === 'categories' 
                            ? 'border-blue-500 text-blue-600' 
                            : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300']">
                    <i class="fas fa-layer-group mr-2"></i>Categorías
                </button>
            </nav>
        </div>

        <!-- Contenido de Tabs -->
        <div class="bg-white rounded-lg shadow overflow-hidden">
            
            <!-- Tab: Vista General -->
            <div v-if="activeTab === 'general'" class="p-6">
                <div class="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    <!-- Top Productos -->
                    <div class="border rounded-lg p-4">
                        <h3 class="font-semibold text-gray-700 mb-3 flex items-center">
                            <i class="fas fa-crown text-yellow-500 mr-2"></i>
                            Top 5 Productos
                        </h3>
                        <div class="space-y-2">
                            <div v-for="(product, index) in topProducts" :key="product.name" 
                                class="flex items-center justify-between p-2 hover:bg-gray-50 rounded">
                                <div class="flex items-center">
                                    <span class="w-6 h-6 flex items-center justify-center rounded-full text-xs font-bold"
                                        :class="index === 0 ? 'bg-yellow-100 text-yellow-700' : 
                                                index === 1 ? 'bg-gray-100 text-gray-700' :
                                                index === 2 ? 'bg-orange-100 text-orange-700' :
                                                'bg-blue-50 text-blue-600'">
                                        {{ index + 1 }}
                                    </span>
                                    <span class="ml-2 text-sm">{{ truncateText(product.name, 30) }}</span>
                                </div>
                                <div class="text-right">
                                    <div class="font-semibold">${{ formatCurrency(product.sales) }}</div>
                                    <div class="text-xs text-gray-500">{{ product.quantity }} unid.</div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <!-- Resumen por Estado -->
                    <div class="border rounded-lg p-4">
                        <h3 class="font-semibold text-gray-700 mb-3 flex items-center">
                            <i class="fas fa-chart-bar text-blue-500 mr-2"></i>
                            Ventas por Estado
                        </h3>
                        <div class="space-y-3">
                            <template v-if="totalOrders > 0">
                                <div v-for="(data, status) in reportData.summaryByStatus" :key="status"                                 
                                    class="flex items-center justify-between p-2 hover:bg-gray-50 rounded">
                                    <div class="flex items-center">
                                        <span class="w-2 h-2 rounded-full mr-2" 
                                            :class="getStatusColor(status)"></span>
                                        <span class="text-sm capitalize">{{ getStatusLabel(status) }}</span>
                                        <span class="ml-2 text-xs text-gray-500">({{ data.orderCount }} órdenes)</span>
                                    </div>
                                    <div class="font-semibold">${{ formatCurrency(data.totalSales) }}</div>
                                </div>
                            </template>
                            <div v-if="Object.values(reportData.summaryByStatus).filter(d => d.orderCount > 0).length === 0" 
                                class="text-gray-400 text-center py-4">
                                No hay datos por estado
                            </div>
                        </div>
                    </div>

                    <!-- Top Categorías -->
                    <div class="border rounded-lg p-4 lg:col-span-2">
                        <h3 class="font-semibold text-gray-700 mb-3 flex items-center">
                            <i class="fas fa-pie-chart text-green-500 mr-2"></i>
                            Ventas por Categoría
                        </h3>
                        <div class="grid grid-cols-1 md:grid-cols-2 gap-3">
                            <div v-for="(total, category) in sortedCategories" :key="category"
                                class="flex items-center justify-between p-2 hover:bg-gray-50 rounded">
                                <span class="text-sm">{{ category }}</span>
                                <div class="flex items-center">
                                    <div class="w-24 h-2 bg-gray-200 rounded-full mr-3">
                                        <div class="h-2 rounded-full bg-green-500" 
                                            :style="{ width: getCategoryPercentage(total) + '%' }"></div>
                                    </div>
                                    <span class="font-semibold text-sm">${{ formatCurrency(total) }}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Tab: Por Estado -->
            <div v-if="activeTab === 'byStatus'" class="p-6">
                <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <template v-if="totalOrders > 0">
                        <div v-for="(data, status) in reportData.summaryByStatus" :key="status"
                            class="border rounded-lg overflow-hidden">
                            <div class="p-4" :class="getStatusBgColor(status)">
                                <h3 class="font-semibold text-white flex items-center justify-between">
                                    <span class="capitalize">{{status}} - {{ getStatusLabel(status) }}</span>
                                    <span class="text-sm opacity-90">{{ data.orderCount }} órdenes</span>
                                </h3>
                            </div>
                            <div class="p-4">
                                <div class="mb-3">
                                    <div class="text-sm text-gray-600">Total Ventas</div>
                                    <div class="text-xl font-bold text-gray-800">${{ formatCurrency(data.totalSales) }}</div>
                                </div>
                                
                                <h4 class="text-xs uppercase text-gray-500 font-semibold mb-2">Productos</h4>
                                <div class="space-y-2 max-h-48 overflow-y-auto">
                                    <template v-for="(sales, product) in data.salesByProduct">
                                        <div v-if="sales > 0" :key="product" class="flex items-center justify-between text-sm">
                                            <span class="text-gray-600">{{ truncateText(product, 25) }}</span>
                                            <div class="text-right">
                                                <span class="font-semibold">${{ formatCurrency(sales) }}</span>
                                                <span class="text-xs text-gray-500 ml-2">
                                                    ({{ data.quantityOfProductsSold[product] || 0 }})
                                                </span>
                                            </div>
                                        </div>
                                    </template>
                                    <div v-if="Object.values(data.salesByProduct).filter(s => s > 0).length === 0"
                                        class="text-gray-400 text-center py-2 text-sm">
                                        Sin productos vendidos
                                    </div>
                                </div>
                            </div>
                        </div>
                    </template>
                </div>
            </div>

            <!-- Tab: Productos -->
            <div v-if="activeTab === 'products'" class="p-6">
               <div class="mb-4 flex justify-between items-center">
                    <h3 class="font-semibold text-gray-700">Listado de Productos</h3>
                    <div class="relative">
                        <input type="text" 
                            v-model="productSearch"
                            placeholder="Buscar producto..."
                            class="border rounded-lg pl-8 pr-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-300">
                        <i class="fas fa-search absolute left-3 top-3 text-gray-400 text-xs"></i>
                    </div>
                </div>
                
                <div class="overflow-x-auto">
                    <table class="min-w-full divide-y divide-gray-200">
                        <thead class="bg-gray-50">
                            <tr>
                                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Producto</th>
                                <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Cantidad</th>
                                <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Ventas</th>
                                <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">% del Total</th>
                            </tr>
                        </thead>
                        <tbody class="bg-white divide-y divide-gray-200">
                            <tr v-for="(quantity, product) in filteredProducts" :key="product"
                                class="hover:bg-gray-50 transition">
                                <td class="px-4 py-3 text-sm text-gray-900">{{ product }}</td>
                                <td class="px-4 py-3 text-sm text-gray-600 text-right">{{ quantity }}</td>
                                <td class="px-4 py-3 text-sm font-semibold text-right">
                                    ${{ formatCurrency(reportData.generalTotal.salesByProduct[product]) }}
                                </td>
                                <td class="px-4 py-3 text-sm text-gray-600 text-right">
                                    {{ getProductPercentage(product) }}%
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div> 

            <!-- Tab: Categorías -->
            <div v-if="activeTab === 'categories'" class="p-6">
                <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    <div v-for="(total, category) in sortedCategories" :key="category"
                        class="border rounded-lg p-4 hover:shadow-md transition">
                        <h4 class="font-semibold text-gray-700 mb-2">{{ category }}</h4>
                        <div class="text-2xl font-bold text-gray-800 mb-2">${{ formatCurrency(total) }}</div>
                        <div class="w-full bg-gray-200 rounded-full h-2 mb-2">
                            <div class="h-2 rounded-full bg-blue-500" 
                                :style="{ width: getCategoryPercentage(total) + '%' }"></div>
                        </div>
                        <div class="text-xs text-gray-500">
                            {{ getCategoryProducts(category) }} productos
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import StaticsPDFReport from '@/components/marketplace/StaticsPDFReport.vue';
import StaticsExcelReport from '@/components/marketplace/StaticsExcelReport.vue';

export default {
    name: 'MarketplaceReportStatics',
    props: {
        reportData: {
            type: Object,
            required: true
        },
        filters: {
            type: Object,
            default: () => ({})
        }
    },
    components: {
        StaticsPDFReport,
        StaticsExcelReport
    },
    mounted() {
        console.log('MarketplaceReportStatics - reportData:', this.reportData);
        console.log('MarketplaceReportStatics - filters:', this.filters);
    },
    data() {
        return {
            activeTab: 'general',
            productSearch: '',
        }
    },
    computed: {
        currentDate() {
            const date = new Date();
            return date.toISOString().split('T')[0];
        },
        // Total de órdenes
        totalOrders() {
            return Object.values(this.reportData?.summaryByStatus || {})
                .reduce((acc, curr) => acc + (curr.orderCount || 0), 0);
        },
        
        // Total de productos únicos
        totalUniqueProducts() {
            return Object.keys(this.reportData?.generalTotal?.quantityOfProductsSold || {})
                .filter(p => this.reportData.generalTotal.quantityOfProductsSold[p] > 0)
                .length;
        },
        
        // Total de categorías
        totalCategories() {
            return Object.keys(this.reportData?.generalTotal?.salesByCategory || {})
                .filter(c => this.reportData.generalTotal.salesByCategory[c] > 0)
                .length;
        },
        
        // Top 5 productos
        topProducts() {
            const products = [];
            Object.entries(this.reportData?.generalTotal?.salesByProduct || {}).forEach(([name, sales]) => {
                if (sales > 0) {
                    products.push({
                        name,
                        sales,
                        quantity: this.reportData.generalTotal.quantityOfProductsSold[name] || 0
                    });
                }
            });
            return products.sort((a, b) => b.sales - a.sales).slice(0, 5);
        },
        
        // Categorías ordenadas
        sortedCategories() {
            return Object.fromEntries(
                Object.entries(this.reportData?.generalTotal?.salesByCategory || {})
                    .filter(([_, total]) => total > 0)
                    .sort((a, b) => b[1] - a[1])
            );
        },
        
        // Productos filtrados por búsqueda
        filteredProducts() {
            const products = this.reportData?.generalTotal?.quantityOfProductsSold || {};
            if (!this.productSearch) {
                return Object.fromEntries(
                    Object.entries(products).filter(([_, qty]) => qty > 0)
                );
            }
            const searchLower = this.productSearch.toLowerCase();
            return Object.fromEntries(
                Object.entries(products)
                    .filter(([name, qty]) => 
                        qty > 0 && name.toLowerCase().includes(searchLower)
                    )
            );
        }
    },
    methods: {
        formatCurrency(value) {
            return value?.toFixed(2) || '0.00';
        },
        
        truncateText(text, length) {
            if (!text) return '';
            return text.length > length ? text.substring(0, length) + '...' : text;
        },
        
        getStatusLabel(status) {
            const labels = {
                created: 'Creada',
                pending: 'Pendiente',
                paid: 'Pagada',
                cancelled: 'Cancelada',
                completed: 'Completada'
            };
            return labels[status] || status;
        },
        
        getStatusColor(status) {
            const colors = {
                created: 'bg-gray-400',
                pending: 'bg-yellow-400',
                paid: 'bg-green-400',
                cancelled: 'bg-red-500',
                completed: 'bg-blue-500'
            };
            return colors[status] || 'bg-gray-400';
        },
        
        getStatusBgColor(status) {
            const colors = {
                created: 'bg-gray-500',
                pending: 'bg-yellow-500',
                paid: 'bg-green-500',
                cancelled: 'bg-pink-700',
                completed: 'bg-teal-500'
            };
            return colors[status] || 'bg-gray-500';
        },
        
        getCategoryPercentage(total) {
            if (!this.reportData?.generalTotal?.totalSales) return 0;
            return ((total / this.reportData.generalTotal.totalSales) * 100).toFixed(1);
        },
        
        getProductPercentage(product) {
            const sales = this.reportData?.generalTotal?.salesByProduct[product] || 0;
            const total = this.reportData?.generalTotal?.totalSales || 0;
            if (!total) return 0;
            return ((sales / total) * 100).toFixed(1);
        },
        
        getCategoryProducts(category) {
            // Contar productos en esta categoría
            let count = 0;
            // Esto es una simplificación - idealmente tendrías un mapa de productos por categoría
            return Object.keys(this.reportData?.generalTotal?.salesByProduct || {}).length;
        },
        
        exportToPDF() {
            this.$emit('export-pdf', this.reportData);
        },
        
        exportToExcel() {
            this.$emit('export-excel', this.reportData);
        }
    }
}
</script>

<style scoped>
.overflow-y-auto::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}

.overflow-y-auto::-webkit-scrollbar-track {
    background: #f1f1f1;
    border-radius: 10px;
}

.overflow-y-auto::-webkit-scrollbar-thumb {
    background: #c1c1c1;
    border-radius: 10px;
}

.overflow-y-auto::-webkit-scrollbar-thumb:hover {
    background: #a1a1a1;
}
</style>