<!-- components/marketplace/SalesPDFReport.vue -->
<template>
  <button @click="exportPdf" class="pdf-export-btn" :disabled="loading">
    <i class="fa fa-spinner fa-pulse mr-2" v-if="loading"></i>
    <i class="fa fa-file-pdf mr-2" v-else></i>
    {{ loading ? 'Generando PDF...' : 'PDF' }}
  </button>
</template>

<script>
import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";

export default {
  name: "SalesPDFReport",
  props: {
    reportData: {
      type: Array, // Array de órdenes
      required: true
    },
    filters: {
      type: Object,
      default: () => ({})
    },
    filename: {
      type: String,
      default: "reporte-ventas-usuario.pdf"
    }
  },
  data() {
    return {
      loading: false
    };
  },
  computed: {
    userInfo() {
      if (!this.reportData || !this.reportData.length) return null;
      return this.reportData[0]?.marketplace_user || null;
    },
    summaryByStatus() {
      const summary = {
        created: { count: 0, total: 0 },
        pending: { count: 0, total: 0 },
        paid: { count: 0, total: 0 },
        cancelled: { count: 0, total: 0 },
        completed: { count: 0, total: 0 }
      };

      this.reportData.forEach(order => {
        if (summary[order.status]) {
          summary[order.status].count += 1;
          summary[order.status].total += parseFloat(order.amount || 0);
        }
      });

      return summary;
    },
    productSummary() {
      const summary = {};

      this.reportData.forEach(order => {
        const items = order.items || [];
        items.forEach(item => {
          const quantity = parseFloat(item.quantity || 0);
          const total = parseFloat(item.final_price || 0) * quantity;

          if (!summary[item.name]) {
            summary[item.name] = {
              quantity: 0,
              total: 0,
              price: parseFloat(item.final_price || 0)
            };
          }

          summary[item.name].quantity += quantity;
          summary[item.name].total += total;
        });
      });

      return summary;
    },
    totalOrders() {
      return this.reportData?.length || 0;
    },
    totalSales() {
      return this.reportData.reduce((sum, order) => sum + parseFloat(order.amount || 0), 0);
    },
    currentDate() {
      const date = new Date();
      return date.toLocaleDateString('es-ES', {
        day: 'numeric',
        month: 'long',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    }
  },
  methods: {
    async exportPdf() {
      try {
        this.loading = true;
        await this.generatePdf();
      } catch (error) {
        console.error("Error exportando PDF:", error);
        alert("Error al generar el PDF del reporte.");
      } finally {
        this.loading = false;
      }
    },

    async generatePdf() {
      const pdf = new jsPDF("p", "mm", "a4");
      const margin = 15;
      let yPosition = margin;
      
      // ===== HEADER PRINCIPAL =====
      pdf.setFillColor(31, 41, 55); // gray-800
      pdf.rect(0, 0, 210, 35, 'F');
      
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(20);
      pdf.setTextColor(255, 255, 255);
      pdf.text("REPORTE DE VENTAS POR USUARIO", margin, yPosition + 10);
      
      pdf.setFontSize(10);
      pdf.setFont("helvetica", "normal");
      pdf.text(`Generado: ${this.currentDate}`, 210 - margin - pdf.getTextWidth(`Generado: ${this.currentDate}`), yPosition + 17);
      
      // Información del usuario en el header
      if (this.userInfo) {
        pdf.setFontSize(9);
        pdf.setTextColor(31,41,55);
        pdf.text(`Usuario: ${this.userInfo.first_name || 'N/A'} | Email: ${this.userInfo.email || 'N/A'}`, margin, yPosition + 27);
      }
      
      pdf.setDrawColor(209, 213, 219);
      pdf.line(margin, 40, 210 - margin, 40);
      
      yPosition = 50;
      
      // ===== FILTROS APLICADOS =====
      if (Object.keys(this.filters).length > 0) {
        pdf.setFillColor(243, 244, 246);
        pdf.rect(margin, yPosition - 5, 50, 8, 'F');
        
        pdf.setFont("helvetica", "bold");
        pdf.setFontSize(12);
        pdf.setTextColor(31, 41, 55);
        pdf.text("Filtros aplicados", margin + 3, yPosition);
        
        yPosition += 10;
        
        pdf.setFont("helvetica", "normal");
        pdf.setFontSize(9);
        pdf.setTextColor(75, 85, 99);
        
        let filterText = '';
        if (this.filters.email) filterText += `Email: ${this.filters.email} | `;
        if (this.filters.order_status) {
          filterText += `Estado: ${this.getStatusLabel(this.filters.order_status)} | `;
        }
        if (this.filters.date_ini && this.filters.date_end) {
          filterText += `Fechas: ${this.filters.date_ini} al ${this.filters.date_end} | `;
        }
        if (this.filters.reference) filterText += `Ref: ${this.filters.reference} | `;
        
        filterText = filterText.replace(/\|\s*$/, '');
        
        const filterLines = this.splitTextToLines(pdf, filterText, 170);
        filterLines.forEach((line, index) => {
          pdf.text(line, margin, yPosition + (index * 4));
        });
        
        yPosition += (filterLines.length * 4) + 10;
      }
      
      // ===== TARJETAS DE RESUMEN =====
      // Total Ventas
      pdf.setFillColor(59, 130, 246); // blue-500
      pdf.roundedRect(margin, yPosition, 85, 25, 3, 3, 'F');
      pdf.setTextColor(255, 255, 255);
      pdf.setFontSize(10);
      pdf.setFont("helvetica", "normal");
      pdf.text("Ventas Totales", margin + 5, yPosition + 8);
      pdf.setFontSize(16);
      pdf.setFont("helvetica", "bold");
      pdf.text(`$${this.totalSales.toFixed(2)}`, margin + 5, yPosition + 20);
      
      // Órdenes
      pdf.setFillColor(34, 197, 94); // green-500
      pdf.roundedRect(210 - margin - 85, yPosition, 85, 25, 3, 3, 'F');
      pdf.setTextColor(255, 255, 255);
      pdf.setFontSize(10);
      pdf.setFont("helvetica", "normal");
      pdf.text("Órdenes", 210 - margin - 80, yPosition + 8);
      pdf.setFontSize(16);
      pdf.setFont("helvetica", "bold");
      pdf.text(this.totalOrders.toString(), 210 - margin - 80, yPosition + 20);
      
      yPosition += 35;
      
      // Productos diferentes
      pdf.setFillColor(168, 85, 247); // purple-500
      pdf.roundedRect(margin, yPosition, 85, 25, 3, 3, 'F');
      pdf.setTextColor(255, 255, 255);
      pdf.setFontSize(10);
      pdf.setFont("helvetica", "normal");
      pdf.text("Productos", margin + 5, yPosition + 8);
      pdf.setFontSize(16);
      pdf.setFont("helvetica", "bold");
      pdf.text(Object.keys(this.productSummary).length.toString(), margin + 5, yPosition + 20);
      
      // Ticket promedio
      const avgTicket = this.totalOrders > 0 ? this.totalSales / this.totalOrders : 0;
      pdf.setFillColor(234, 179, 8); // yellow-500
      pdf.roundedRect(210 - margin - 85, yPosition, 85, 25, 3, 3, 'F');
      pdf.setTextColor(255, 255, 255);
      pdf.setFontSize(10);
      pdf.setFont("helvetica", "normal");
      pdf.text("Ticket Promedio", 210 - margin - 80, yPosition + 8);
      pdf.setFontSize(14);
      pdf.setFont("helvetica", "bold");
      pdf.text(`$${avgTicket.toFixed(2)}`, 210 - margin - 80, yPosition + 20);
      
      yPosition += 40;
      
      // ===== TABLA DE ÓRDENES =====
      yPosition = this.addOrdersTable(pdf, margin, yPosition);
      
      // ===== TOP PRODUCTOS =====
      if (yPosition > 250) {
        pdf.addPage();
        yPosition = margin + 10;
      }
      yPosition = this.addProductsTable(pdf, margin, yPosition);
      
      // ===== RESUMEN POR ESTADO =====
      if (yPosition > 250) {
        pdf.addPage();
        yPosition = margin + 10;
      }
      yPosition = this.addStatusSummary(pdf, margin, yPosition);
      
      // ===== FOOTER =====
      const pageCount = pdf.getNumberOfPages();
      for (let i = 1; i <= pageCount; i++) {
        pdf.setPage(i);
        pdf.setFont("helvetica", "normal");
        pdf.setFontSize(8);
        pdf.setTextColor(156, 163, 175);
        pdf.text(`Documento generado el ${this.currentDate}`, margin, 290);
        pdf.text("Reporte de Ventas por Usuario", 210 - margin - pdf.getTextWidth("Reporte de Ventas por Usuario"), 290);
        pdf.text(`Página ${i} de ${pageCount}`, 105, 290, { align: 'center' });
      }
      
      pdf.save(this.filename);
    },

    addOrdersTable(pdf, margin, yPosition) {
      pdf.setFillColor(243, 244, 246);
      pdf.rect(margin, yPosition - 5, 40, 8, 'F');
      
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(14);
      pdf.setTextColor(31, 41, 55);
      pdf.text("Órdenes", margin + 3, yPosition);
      
      yPosition += 10;
      
      const ordersData = this.reportData.map(order => [
        order.reference,
        this.formatDate(order.order_date),
        this.getStatusLabel(order.status),
        order.items?.length || 0,
        `$${parseFloat(order.amount || 0).toFixed(2)}`
      ]);
      
      if (ordersData.length > 0) {
        autoTable(pdf, {
          startY: yPosition,
          head: [['Referencia', 'Fecha', 'Estado', 'Items', 'Total']],
          body: ordersData,
          theme: 'striped',
          headStyles: { fillColor: [31, 41, 55], textColor: 255, fontStyle: 'bold' },
          columnStyles: {
            0: { cellWidth: 65 },
            1: { cellWidth: 30 },
            2: { cellWidth: 30 },
            3: { cellWidth: 20, halign: 'center' },
            4: { cellWidth: 30, halign: 'right' }
          },
          margin: { left: margin, right: margin }
        });
        
        return pdf.lastAutoTable.finalY + 15;
      } else {
        pdf.setFont("helvetica", "italic");
        pdf.setTextColor(156, 163, 175);
        pdf.text("No hay órdenes para mostrar", margin, yPosition + 5);
        return yPosition + 15;
      }
    },

    addProductsTable(pdf, margin, yPosition) {
      pdf.setFillColor(243, 244, 246);
      pdf.rect(margin, yPosition - 5, 45, 8, 'F');
      
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(14);
      pdf.setTextColor(31, 41, 55);
      pdf.text("Productos", margin + 3, yPosition);
      
      yPosition += 10;
      
      const productsData = Object.entries(this.productSummary)
        .sort((a, b) => b[1].total - a[1].total)
        .map(([name, info]) => [
          name,
          info.quantity,
          `$${info.total.toFixed(2)}`
        ]);
      
      if (productsData.length > 0) {
        autoTable(pdf, {
          startY: yPosition,
          head: [['Producto', 'Cantidad', 'Total']],
          body: productsData,
          theme: 'striped',
          headStyles: { fillColor: [31, 41, 55], textColor: 255, fontStyle: 'bold' },
          columnStyles: {
            0: { cellWidth: 110 },
            1: { cellWidth: 30, halign: 'center' },
            2: { cellWidth: 35, halign: 'right' }
          },
          margin: { left: margin, right: margin }
        });
        
        return pdf.lastAutoTable.finalY + 15;
      } else {
        pdf.setFont("helvetica", "italic");
        pdf.setTextColor(156, 163, 175);
        pdf.text("No hay productos para mostrar", margin, yPosition + 5);
        return yPosition + 15;
      }
    },

    addStatusSummary(pdf, margin, yPosition) {
      pdf.setFillColor(243, 244, 246);
      pdf.rect(margin, yPosition - 5, 60, 8, 'F');
      
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(14);
      pdf.setTextColor(31, 41, 55);
      pdf.text("Resumen por Estado", margin + 3, yPosition);
      
      yPosition += 10;
      
      const statusData = [];
      Object.entries(this.summaryByStatus).forEach(([status, info]) => {
        if (info.count > 0 || info.total > 0) {
          statusData.push([
            this.getStatusLabel(status),
            info.count,
            `$${info.total.toFixed(2)}`
          ]);
        }
      });
      
      if (statusData.length > 0) {
        autoTable(pdf, {
          startY: yPosition,
          head: [['Estado', 'Órdenes', 'Total']],
          body: statusData,
          theme: 'striped',
          headStyles: { fillColor: [31, 41, 55], textColor: 255, fontStyle: 'bold' },
          columnStyles: {
            0: { cellWidth: 85 },
            1: { cellWidth: 40, halign: 'center' },
            2: { cellWidth: 50, halign: 'right' }
          },
          margin: { left: margin, right: margin }
        });
        
        return pdf.lastAutoTable.finalY + 15;
      } else {
        pdf.setFont("helvetica", "italic");
        pdf.setTextColor(156, 163, 175);
        pdf.text("No hay datos por estado", margin, yPosition + 5);
        return yPosition + 15;
      }
    },

    splitTextToLines(pdf, text, maxWidth) {
      const words = text.split(' ');
      const lines = [];
      let currentLine = words[0];

      for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = pdf.getTextWidth(currentLine + " " + word);
        if (width < maxWidth) {
          currentLine += " " + word;
        } else {
          lines.push(currentLine);
          currentLine = word;
        }
      }
      lines.push(currentLine);
      return lines;
    },

    formatDate(date) {
      if (!date) return '';
      const d = new Date(date);
      return d.toLocaleDateString('es-ES');
    },

    getStatusLabel(status) {
      const labels = {
        created: 'Creada',
        pending: 'Pendiente',
        paid: 'Pagada',
        cancelled: 'Cancelada',
        completed: 'Completada'
      };
      return labels[status] || status;
    }
  }
};
</script>

<style scoped>
.pdf-export-btn {
  padding: 5px 10px;
  background-color: #890000;
  color: white;
  border: none;
  cursor: pointer;
  border-radius: 6px;
  font-weight: 600;
  transition: all 0.2s;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
}
.pdf-export-btn:hover:not(:disabled) {
  background-color: #a50101;
  transform: translateY(-1px);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}
.pdf-export-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
</style>