<!-- components/marketplace/SalesExcelReport.vue -->
<template>
  <button @click="exportExcel" class="excel-export-btn" :disabled="loading">
    <i class="fa fa-spinner fa-pulse mr-2" v-if="loading"></i>
    <i class="fa fa-file-excel mr-2" v-else></i>
    {{ loading ? 'Generando Excel...' : 'Excel' }}
  </button>
</template>

<script>
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';

export default {
  name: "StaticsExcelReport",
  props: {
    reportData: {
      type: Object,
      required: true
    },
    filters: {
      type: Object,
      default: () => ({})
    },
    filename: {
      type: String,
      default: "reporte-ventas.xlsx"
    }
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    async exportExcel() {
      try {
        this.loading = true;
        
        // Crear workbook
        const wb = XLSX.utils.book_new();
        
        // Hoja de resumen
        const summarySheet = this.createSummarySheet();
        XLSX.utils.book_append_sheet(wb, summarySheet, "Resumen");
        
        // Hoja de ventas por estado
        const statusSheet = this.createStatusSheet();
        XLSX.utils.book_append_sheet(wb, statusSheet, "Ventas por Estado");
        
        // Hoja de productos
        const productsSheet = this.createProductsSheet();
        XLSX.utils.book_append_sheet(wb, productsSheet, "Productos");
        
        // Hoja de categorías
        const categoriesSheet = this.createCategoriesSheet();
        XLSX.utils.book_append_sheet(wb, categoriesSheet, "Categorías");
        
        // Hoja de filtros (información adicional)
        const filtersSheet = this.createFiltersSheet();
        XLSX.utils.book_append_sheet(wb, filtersSheet, "Filtros Aplicados");
        
        // Generar archivo
        const excelBuffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        const data = new Blob([excelBuffer], { type: 'application/octet-stream' });
        saveAs(data, this.filename);
        
      } catch (error) {
        console.error("Error exportando Excel:", error);
        alert("Error al generar el archivo Excel.");
      } finally {
        this.loading = false;
      }
    },

    createSummarySheet() {
      const report = this.reportData;
      
      // Calcular totales
      const totalOrders = Object.values(report.summaryByStatus || {}).reduce((acc, curr) => acc + (curr.orderCount || 0), 0);
      const totalProducts = Object.keys(report.generalTotal?.quantityOfProductsSold || {}).filter(p => report.generalTotal.quantityOfProductsSold[p] > 0).length;
      const totalCategories = Object.keys(report.generalTotal?.salesByCategory || {}).filter(c => report.generalTotal.salesByCategory[c] > 0).length;
      
      // Datos del resumen
      const data = [
        ['REPORTE DE VENTAS - RESUMEN GENERAL'],
        [],
        ['Métrica', 'Valor'],
        ['Ventas Totales', `$${(report.generalTotal?.totalSales || 0).toFixed(2)}`],
        ['Total Órdenes', totalOrders],
        ['Total Productos', totalProducts],
        ['Total Categorías', totalCategories],
        [],
        ['Fecha de generación', new Date().toLocaleString('es-ES')]
      ];
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      // Estilos (ancho de columnas)
      ws['!cols'] = [
        { wch: 25 },
        { wch: 20 }
      ];
      
      return ws;
    },

    createStatusSheet() {
      const report = this.reportData;
      const statusMap = {
        'created': 'Creada',
        'pending': 'Pendiente',
        'paid': 'Pagada',
        'completed': 'Completada',
        'cancelled': 'Cancelada'
      };
      
      const data = [
        ['VENTAS POR ESTADO'],
        [],
        ['Estado', 'Órdenes', 'Total Ventas', 'Productos Vendidos']
      ];
      
      Object.entries(report.summaryByStatus || {}).forEach(([status, statusData]) => {
        if (statusData.orderCount > 0 || statusData.totalSales > 0) {
          const productCount = Object.keys(statusData.quantityOfProductsSold || {})
            .filter(p => statusData.quantityOfProductsSold[p] > 0).length;
          
          data.push([
            statusMap[status] || status,
            statusData.orderCount || 0,
            `$${(statusData.totalSales || 0).toFixed(2)}`,
            productCount
          ]);
          
          // Agregar productos de este estado como subdetalle
          Object.entries(statusData.salesByProduct || {}).forEach(([product, sales]) => {
            if (sales > 0) {
              data.push([
                `  └ ${product}`,
                statusData.quantityOfProductsSold[product] || 0,
                `$${sales.toFixed(2)}`,
                ''
              ]);
            }
          });
          data.push([]); // línea en blanco entre estados
        }
      });
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 40 },
        { wch: 10 },
        { wch: 15 },
        { wch: 15 }
      ];
      
      return ws;
    },

    createProductsSheet() {
      const report = this.reportData;
      const totalSales = report.generalTotal?.totalSales || 0;
      
      const data = [
        ['LISTADO DE PRODUCTOS'],
        [],
        ['Producto', 'Cantidad Vendida', 'Ventas Totales', '% del Total']
      ];
      
      // Ordenar productos por ventas (mayor a menor)
      const products = [];
      Object.entries(report.generalTotal?.salesByProduct || {}).forEach(([name, sales]) => {
        if (sales > 0) {
          products.push({
            name,
            sales,
            quantity: report.generalTotal.quantityOfProductsSold[name] || 0
          });
        }
      });
      
      products.sort((a, b) => b.sales - a.sales).forEach(p => {
        const percentage = totalSales > 0 ? ((p.sales / totalSales) * 100).toFixed(1) : 0;
        data.push([
          p.name,
          p.quantity,
          `$${p.sales.toFixed(2)}`,
          `${percentage}%`
        ]);
      });
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 45 },
        { wch: 15 },
        { wch: 15 },
        { wch: 10 }
      ];
      
      return ws;
    },

    createCategoriesSheet() {
      const report = this.reportData;
      const totalSales = report.generalTotal?.totalSales || 0;
      
      const data = [
        ['VENTAS POR CATEGORÍA'],
        [],
        ['Categoría', 'Ventas Totales', '% del Total']
      ];
      
      Object.entries(report.generalTotal?.salesByCategory || {})
        .filter(([_, total]) => total > 0)
        .sort((a, b) => b[1] - a[1])
        .forEach(([category, total]) => {
          const percentage = totalSales > 0 ? ((total / totalSales) * 100).toFixed(1) : 0;
          data.push([
            category,
            `$${total.toFixed(2)}`,
            `${percentage}%`
          ]);
        });
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 35 },
        { wch: 15 },
        { wch: 10 }
      ];
      
      return ws;
    },

    createFiltersSheet() {
      const data = [
        ['FILTROS APLICADOS EN LA BÚSQUEDA'],
        [],
        ['Filtro', 'Valor']
      ];
      
      if (this.filters.email) data.push(['Email', this.filters.email]);
      if (this.filters.order_status) {
        const statusMap = {
          'created': 'Creada',
          'pending': 'Pendiente',
          'paid': 'Pagada',
          'cancelled': 'Cancelada',
          'completed': 'Completada'
        };
        data.push(['Estado', statusMap[this.filters.order_status] || this.filters.order_status]);
      }
      if (this.filters.date_ini && this.filters.date_end) {
        data.push(['Rango de fechas', `${this.filters.date_ini} al ${this.filters.date_end}`]);
      }
      if (this.filters.reference) data.push(['Referencia', this.filters.reference]);
      if (this.filters.min_amount) data.push(['Monto mínimo', `$${this.filters.min_amount}`]);
      if (this.filters.max_amount) data.push(['Monto máximo', `$${this.filters.max_amount}`]);
      
      data.push([]);
      data.push(['Fecha de exportación', new Date().toLocaleString('es-ES')]);
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 25 },
        { wch: 40 }
      ];
      
      return ws;
    }
  }
};
</script>

<style scoped>
.excel-export-btn {
  padding: 5px 10px;
  background-color: #016526;
  color: white;
  border: none;
  cursor: pointer;
  border-radius: 6px;
  font-weight: 600;
  transition: all 0.2s;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
}
.excel-export-btn:hover:not(:disabled) {
  background-color: #008531;
  transform: translateY(-1px);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}
.excel-export-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
</style>