import Authorization from "../user/auth.service";

const base_url = "marketplace-items";
const MarketplaceItemService = {
  async getList(filters = {}) {
    try {
      const search_data = {
        auth: "bearer",
        ...filters,
      };
      const { status, data } = await Authorization.checkLogin(`/${base_url}/search-backend`, search_data, "post");
      if (status === 200) {
        const list = [];
        for (let item of data) {
          const option = {
            id: item.id,
            alias: item.alias,
            stock: item.dispo.stock,
            in_offer: item.in_offer ? true : false,
            delivery_free: item.delivery_free ? true : false,
            active: item.active ? true : false,
            sale: item.price_not_discount,
            cost: item.price_cost,
          };
          list.push(option);
        }
        return list;
      }
      // return Authorization.checkLogin(`/${base_url}`, { auth: "bearer" })
      //   .then((res) => {
      //     if (res.status !== 200) {
      //       return {
      //         success: false,
      //         errors: "Fail check login",
      //       };
      //     }

      //     const list = [];
      //     for (let item of res.data) {
      //       const option = {
      //         id: item.id,
      //         alias: item.alias,
      //         stock: item.dispo.stock,
      //         in_offer: item.in_offer ? true : false,
      //         delivery_free: item.delivery_free ? true : false,
      //         active: item.active ? true : false,
      //         sale: item.price_not_discount,
      //         cost: item.price_cost,
      //       };

      //       list.push(option);
      //     }

      //     return list;
      //   })
      //   .catch((e) => {
      //     console.error(e);
      //   });
    } catch (e) {
      console.error(e);
    }
  },
  getSimpleList() {
    try {
      return Authorization.checkLogin(`/${base_url}`, { auth: "bearer" })
        .then((res) => {
          if (res.status !== 200) {
            return {
              success: false,
              errors: "Fail check login",
            };
          }

          const list = [];
          for (let item of res.data) {
            if (item.id !== 1) {
              const option = {
                value: item.id,
                text: item.alias,
              };

              list.push(option);
            }
          }

          return list;
        })
        .catch((e) => {
          console.error(e);
        });
    } catch (e) {
      console.error(e);
    }
  },
  /* getSimpleList(){

    }, */
  async getMarketplaceItem(id) {
    //! Obtiene los datos x un ID
    try {
      const { status, data } = await Authorization.checkLogin(`/${base_url}/${id}`, { auth: "bearer" });
      if (status == 200) {
        return data;
      }
    } catch (e) {
      console.error(e.response);
    }
  },
  async addUpdMarketplaceItem(form_data, is_new = true) {
    try {
      // console.log(form_data);
      form_data.auth = "bearer";
      const { status, data } = is_new
        ? await Authorization.checkLoginImage(`/${base_url}/create`, form_data.form, "post")
        : await Authorization.checkLoginImage(`/${base_url}/upd/${form_data.id}`, form_data.form, "put");
      if (status === 200) {
        return data;
      }
    } catch (e) {
      //! Fail
      console.error(e.response);
    }
    return false;
  },
  async fastUpdate(id, field, value) {
    try {
      let column = field;
      if (field === "cost") column = "price_cost";
      if (field === "sale") column = "price";
      const form_data = {
        auth: "bearer",
        [column]: value,
      };
      const { status, data } = await Authorization.checkLogin(`/${base_url}/fast-upd/${id}`, form_data, "put");
      if (status === 200) {
        return data;
      }
    } catch (e) {
      //! Fail
      console.error(e.response);
    }
    return false;
  },
  async delete(ids) {
    const delete_data = {
      auth: "bearer",
      ids,
    };
    try {
      const { status, data } = await Authorization.checkLogin(`/${base_url}/delete`, delete_data, "post");
      if (status == 200) {
        return this.getList().then((list) => {
          return list;
        });
      }
    } catch (e) {
      //! Fail
      console.error(e.response);
    }
  },
  async search(filters = {}) {
    try {
      const search_data = {
        auth: "bearer",
        ...filters,
      };
      const { status, data } = await Authorization.checkLogin(`/${base_url}/search-backend`, search_data, "post");
      if (status === 200) {
        const list = [];
        for (let item of data) {
          const option = {
            id: item.id,
            alias: item.alias,
            stock: item.dispo.stock,
            in_offer: item.in_offer ? true : false,
            delivery_free: item.delivery_free ? true : false,
            active: item.active ? true : false,
            sale: item.price_not_discount,
            cost: item.price_cost,
          };
          list.push(option);
        }
        return list;
      }
    } catch (e) {
      console.error(e.response);
      return [];
    }
  },

  async searchAndExport(filters = {}, limit = null, offset = 0) {
    try {
      const search_data = {
        auth: "bearer",
        ...filters,
      };
      
      // Agregar parámetros de paginación si se proporcionan
      if (limit !== null) {
        search_data.limit = limit;
      }
      if (offset > 0) {
        search_data.offset = offset;
      }
      
      const { status, data } = await Authorization.checkLogin(`/${base_url}/search-backend`, search_data, "post");
      if (status === 200) {
        const list = [];
        for (let item of data) {
          const option = {
            id: item.id,
            alias: item.alias,
            stock: item.dispo.stock,
            in_offer: item.in_offer ? true : false,
            delivery_free: item.delivery_free ? true : false,
            active: item.active ? true : false,
            sale: item.price_not_discount,
            cost: item.price_cost,
            // Additional fields for export
            description: item.description || '',
            category: item.category?.name || '',
            created_at: item.created_at,
            updated_at: item.updated_at,
          };
          list.push(option);
        }
        return list;
      }
    } catch (e) {
      console.error(e.response);
      return [];
    }
  },

  async getCount(filters = {}) {
    try {
      const search_data = {
        auth: "bearer",
        ...filters,
        count_only: true // Para que el backend solo devuelva el conteo
      };
      
      const { status, data } = await Authorization.checkLogin(`/${base_url}/search-backend`, search_data, "post");
      if (status === 200) {
        return data;
      }
      return 0;
    } catch (e) {
      console.error(e.response);
      return 0;
    }
  },
};

export default MarketplaceItemService;
