<!-- components/marketplace/SalesPDFReport.vue -->
<template>
  <button @click="exportPdf" class="pdf-export-btn" :disabled="loading">
    <i class="fa fa-spinner fa-pulse mr-2" v-if="loading"></i>
    <i class="fa fa-file-pdf mr-2" v-else></i>
    {{ loading ? 'Generando PDF...' : 'PDF' }}
  </button>
</template>

<script>
import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import html2canvas from "html2canvas";

export default {
  name: "StaticsPDFReport",
  props: {
    reportData: {
      type: Object,
      required: true
    },
    filters: {
      type: Object,
      default: () => ({})
    },
    filename: {
      type: String,
      default: "reporte-ventas.pdf"
    },
    targetElement: {
      type: HTMLElement,
      required: false,
      default: null
    }
  },
  data() {
    return {
      loading: false
    };
  },
  computed: {
    currentDate() {
      const date = new Date();
      return date.toLocaleDateString('es-ES', {
        day: 'numeric',
        month: 'long',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    }
  },
  methods: {
    async exportPdf() {
      try {
        this.loading = true;
        
        if (this.targetElement) {
          await this.exportPdfFromHtml();
        } else {
          await this.exportPdfFromTemplate();
        }
        
      } catch (error) {
        console.error("Error exportando PDF:", error);
        alert("Error al generar el PDF del reporte.");
      } finally {
        this.loading = false;
      }
    },

    async exportPdfFromHtml() {
      const pdf = new jsPDF("p", "mm", "a4");
      const element = this.targetElement;
      
      // Opciones para html2canvas
      const options = {
        scale: 2,
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff',
        logging: false,
        windowWidth: element.scrollWidth,
        windowHeight: element.scrollHeight
      };

      try {
        // Capturar el elemento completo
        const canvas = await html2canvas(element, options);
        
        const pageWidth = pdf.internal.pageSize.getWidth();
        const pageHeight = pdf.internal.pageSize.getHeight();
        const margin = 10;

        const pdfUsableWidth = pageWidth - margin * 2;
        const pxPerMm = canvas.width / pdfUsableWidth;
        const pageHeightPx = Math.floor((pageHeight - margin * 2) * pxPerMm);

        let remainingHeightPx = canvas.height;
        let offsetY = 0;

        const pageCanvas = document.createElement("canvas");
        pageCanvas.width = canvas.width;
        pageCanvas.height = Math.min(pageHeightPx, canvas.height);
        const pageCtx = pageCanvas.getContext("2d");

        let pageNumber = 1;

        while (remainingHeightPx > 0) {
          pageCtx.clearRect(0, 0, pageCanvas.width, pageCanvas.height);
          pageCtx.drawImage(
            canvas,
            0,
            offsetY,
            canvas.width,
            pageCanvas.height,
            0,
            0,
            canvas.width,
            pageCanvas.height
          );

          const imgData = pageCanvas.toDataURL("image/png");
          const imgHeightMm = pageCanvas.height / pxPerMm;

          if (offsetY > 0) {
            pdf.addPage();
          }
          
          // Agregar la imagen al PDF
          pdf.addImage(imgData, "PNG", margin, margin, pdfUsableWidth, imgHeightMm, undefined, "FAST");
          
          // Agregar número de página
          pdf.setFont("helvetica", "normal");
          pdf.setFontSize(8);
          pdf.setTextColor(156, 163, 175);
          pdf.text(`Página ${pageNumber}`, pageWidth - margin - 20, pageHeight - margin);
          
          offsetY += pageCanvas.height;
          remainingHeightPx -= pageCanvas.height;
          pageNumber++;

          if (remainingHeightPx > 0 && remainingHeightPx < pageHeightPx) {
            pageCanvas.height = remainingHeightPx;
          }
        }

        // Guardar el PDF
        pdf.save(this.filename);
        
      } catch (error) {
        console.error("Error capturando HTML:", error);
        // Fallback al método de template si falla la captura
        await this.exportPdfFromTemplate();
      }
    },

    async exportPdfFromTemplate() {
      const pdf = new jsPDF("p", "mm", "a4");
      const report = this.reportData;
      const margin = 15;
      let yPosition = margin;
      
      // ===== HEADER PRINCIPAL =====
      // Fondo gris para el header
      pdf.setFillColor(31, 41, 55); // gray-800
      pdf.rect(0, 0, 210, 30, 'F');
      
      // Título del reporte
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(20);
      pdf.setTextColor(255, 255, 255);
      pdf.text("REPORTE DE VENTAS", margin, yPosition + 10);
      
      // Fecha de generación
      pdf.setFontSize(10);
      pdf.setFont("helvetica", "normal");
      pdf.text(`Generado: ${this.currentDate}`, 210 - margin - pdf.getTextWidth(`Generado: ${this.currentDate}`), yPosition + 10);
      
      // Línea separadora
      pdf.setDrawColor(209, 213, 219);
      pdf.line(margin, 35, 210 - margin, 35);
      
      yPosition = 45;
      
      // ===== FILTROS APLICADOS =====
      if (Object.keys(this.filters).length > 0) {
        pdf.setFillColor(243, 244, 246);
        pdf.rect(margin, yPosition - 5, 50, 8, 'F');
        
        pdf.setFont("helvetica", "bold");
        pdf.setFontSize(12);
        pdf.setTextColor(31, 41, 55);
        pdf.text("Filtros aplicados", margin + 3, yPosition);
        
        yPosition += 10;
        
        pdf.setFont("helvetica", "normal");
        pdf.setFontSize(9);
        pdf.setTextColor(75, 85, 99);
        
        let filterText = '';
        if (this.filters.email) filterText += `Email: ${this.filters.email} | `;
        if (this.filters.order_status) {
          const statusMap = {
            'created': 'Creada',
            'pending': 'Pendiente',
            'paid': 'Pagada',
            'cancelled': 'Cancelada',
            'completed': 'Completada'
          };
          filterText += `Estado: ${statusMap[this.filters.order_status] || this.filters.order_status} | `;
        }
        if (this.filters.date_ini && this.filters.date_end) {
          filterText += `Fechas: ${this.filters.date_ini} al ${this.filters.date_end} | `;
        }
        if (this.filters.reference) filterText += `Ref: ${this.filters.reference} | `;
        if (this.filters.min_amount) filterText += `Monto min: $${this.filters.min_amount} | `;
        if (this.filters.max_amount) filterText += `Monto max: $${this.filters.max_amount}`;
        
        // Eliminar el último " | " si existe
        filterText = filterText.replace(/\|\s*$/, '');
        
        const filterLines = this.splitTextToLines(pdf, filterText, 170);
        filterLines.forEach((line, index) => {
          pdf.text(line, margin, yPosition + (index * 4));
        });
        
        yPosition += (filterLines.length * 4) + 10;
      }
      
      // ===== TARJETAS DE RESUMEN =====
      // Total Ventas
      pdf.setFillColor(59, 130, 246); // blue-500
      pdf.roundedRect(margin, yPosition, 85, 25, 3, 3, 'F');
      pdf.setTextColor(255, 255, 255);
      pdf.setFontSize(10);
      pdf.setFont("helvetica", "normal");
      pdf.text("Ventas Totales", margin + 5, yPosition + 8);
      pdf.setFontSize(16);
      pdf.setFont("helvetica", "bold");
      pdf.text(`$${(report.generalTotal?.totalSales || 0).toFixed(2)}`, margin + 5, yPosition + 20);
      
      // Órdenes
      pdf.setFillColor(34, 197, 94); // green-500
      pdf.roundedRect(210 - margin - 85, yPosition, 85, 25, 3, 3, 'F');
      pdf.setTextColor(255, 255, 255);
      pdf.setFontSize(10);
      pdf.setFont("helvetica", "normal");
      pdf.text("Órdenes", 210 - margin - 80, yPosition + 8);
      pdf.setFontSize(16);
      pdf.setFont("helvetica", "bold");
      const totalOrders = Object.values(report.summaryByStatus || {}).reduce((acc, curr) => acc + (curr.orderCount || 0), 0);
      pdf.text(totalOrders.toString(), 210 - margin - 80, yPosition + 20);
      
      yPosition += 35;
      
      // Segunda fila de tarjetas
      // Productos diferentes
      pdf.setFillColor(168, 85, 247); // purple-500
      pdf.roundedRect(margin, yPosition, 85, 25, 3, 3, 'F');
      pdf.setTextColor(255, 255, 255);
      pdf.setFontSize(10);
      pdf.setFont("helvetica", "normal");
      pdf.text("Productos", margin + 5, yPosition + 8);
      pdf.setFontSize(16);
      pdf.setFont("helvetica", "bold");
      const totalProducts = Object.keys(report.generalTotal?.quantityOfProductsSold || {}).filter(p => report.generalTotal.quantityOfProductsSold[p] > 0).length;
      pdf.text(totalProducts.toString(), margin + 5, yPosition + 20);
      
      // Categorías
      pdf.setFillColor(234, 179, 8); // yellow-500
      pdf.roundedRect(210 - margin - 85, yPosition, 85, 25, 3, 3, 'F');
      pdf.setTextColor(255, 255, 255);
      pdf.setFontSize(10);
      pdf.setFont("helvetica", "normal");
      pdf.text("Categorías", 210 - margin - 80, yPosition + 8);
      pdf.setFontSize(16);
      pdf.setFont("helvetica", "bold");
      const totalCategories = Object.keys(report.generalTotal?.salesByCategory || {}).filter(c => report.generalTotal.salesByCategory[c] > 0).length;
      pdf.text(totalCategories.toString(), 210 - margin - 80, yPosition + 20);
      
      yPosition += 40;
      
      // ===== VENTAS POR ESTADO =====
      yPosition = this.addStatusTable(pdf, report, margin, yPosition);
      
      // ===== TOP 5 PRODUCTOS =====
      yPosition = this.addTopProductsTable(pdf, report, margin, yPosition);
      
      // ===== VENTAS POR CATEGORÍA =====
      yPosition = this.addCategoriesTable(pdf, report, margin, yPosition);
      
      // ===== FOOTER =====
      const pageCount = pdf.getNumberOfPages();
      for (let i = 1; i <= pageCount; i++) {
        pdf.setPage(i);
        pdf.setFont("helvetica", "normal");
        pdf.setFontSize(8);
        pdf.setTextColor(156, 163, 175);
        pdf.text(`Documento generado el ${this.currentDate}`, margin, 290);
        pdf.text("Reporte de Ventas - Marketplace", 210 - margin - pdf.getTextWidth("Reporte de Ventas - Marketplace"), 290);
        pdf.text(`Página ${i} de ${pageCount}`, 105, 290, { align: 'center' });
      }
      
      // Guardar el PDF
      pdf.save(this.filename);
    },

    addStatusTable(pdf, report, margin, yPosition) {
      pdf.setFillColor(243, 244, 246);
      pdf.rect(margin, yPosition - 5, 60, 8, 'F');
      
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(14);
      pdf.setTextColor(31, 41, 55);
      pdf.text("Ventas por Estado", margin + 3, yPosition);
      
      yPosition += 10;
      
      const statusData = [];
      const statusMap = {
        'created': 'Creada',
        'pending': 'Pendiente',
        'paid': 'Pagada',
        'completed': 'Completada',
        'cancelled': 'Cancelada'
      };
      
      Object.entries(report.summaryByStatus || {}).forEach(([status, data]) => {
        if (data.orderCount > 0 || data.totalSales > 0) {
          statusData.push([
            statusMap[status] || status,
            data.orderCount || 0,
            `$${(data.totalSales || 0).toFixed(2)}`
          ]);
        }
      });
      
      if (statusData.length > 0) {
        autoTable(pdf, {
          startY: yPosition,
          head: [['Estado', 'Órdenes', 'Total Ventas']],
          body: statusData,
          theme: 'striped',
          headStyles: { fillColor: [31, 41, 55], textColor: 255, fontStyle: 'bold' },
          columnStyles: {
            0: { cellWidth: 70 },
            1: { cellWidth: 50, halign: 'center' },
            2: { cellWidth: 50, halign: 'right' }
          },
          margin: { left: margin, right: margin }
        });
        
        return pdf.lastAutoTable.finalY + 15;
      } else {
        pdf.setFont("helvetica", "italic");
        pdf.setTextColor(156, 163, 175);
        pdf.text("No hay datos de ventas por estado", margin, yPosition + 5);
        return yPosition + 15;
      }
    },

    addTopProductsTable(pdf, report, margin, yPosition) {
      pdf.setFillColor(243, 244, 246);
      pdf.rect(margin, yPosition - 5, 70, 8, 'F');
      
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(14);
      pdf.setTextColor(31, 41, 55);
      pdf.text("Top 5 Productos", margin + 3, yPosition);
      
      yPosition += 10;
      
      const products = [];
      Object.entries(report.generalTotal?.salesByProduct || {}).forEach(([name, sales]) => {
        if (sales > 0) {
          products.push({
            name,
            sales,
            quantity: report.generalTotal.quantityOfProductsSold[name] || 0
          });
        }
      });
      
      const topProducts = products.sort((a, b) => b.sales - a.sales).slice(0, 5);
      
      if (topProducts.length > 0) {
        const productData = topProducts.map((p, index) => [
          `${index + 1}. ${p.name}`,
          p.quantity,
          `$${p.sales.toFixed(2)}`
        ]);
        
        autoTable(pdf, {
          startY: yPosition,
          head: [['Producto', 'Cantidad', 'Ventas']],
          body: productData,
          theme: 'striped',
          headStyles: { fillColor: [31, 41, 55], textColor: 255, fontStyle: 'bold' },
          columnStyles: {
            0: { cellWidth: 100 },
            1: { cellWidth: 35, halign: 'center' },
            2: { cellWidth: 35, halign: 'right' }
          },
          margin: { left: margin, right: margin }
        });
        
        return pdf.lastAutoTable.finalY + 15;
      } else {
        pdf.setFont("helvetica", "italic");
        pdf.setTextColor(156, 163, 175);
        pdf.text("No hay productos para mostrar", margin, yPosition + 5);
        return yPosition + 15;
      }
    },

    addCategoriesTable(pdf, report, margin, yPosition) {
      pdf.setFillColor(243, 244, 246);
      pdf.rect(margin, yPosition - 5, 70, 8, 'F');
      
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(14);
      pdf.setTextColor(31, 41, 55);
      pdf.text("Ventas por Categoría", margin + 3, yPosition);
      
      yPosition += 10;
      
      const categoryData = [];
      Object.entries(report.generalTotal?.salesByCategory || {})
        .filter(([_, total]) => total > 0)
        .sort((a, b) => b[1] - a[1])
        .forEach(([category, total]) => {
          const percentage = report.generalTotal.totalSales > 0 
            ? ((total / report.generalTotal.totalSales) * 100).toFixed(1) 
            : 0;
          categoryData.push([
            category,
            `$${total.toFixed(2)}`,
            `${percentage}%`
          ]);
        });
      
      if (categoryData.length > 0) {
        autoTable(pdf, {
          startY: yPosition,
          head: [['Categoría', 'Total', '%']],
          body: categoryData,
          theme: 'striped',
          headStyles: { fillColor: [31, 41, 55], textColor: 255, fontStyle: 'bold' },
          columnStyles: {
            0: { cellWidth: 100 },
            1: { cellWidth: 40, halign: 'right' },
            2: { cellWidth: 30, halign: 'right' }
          },
          margin: { left: margin, right: margin }
        });
        
        return pdf.lastAutoTable.finalY + 15;
      } else {
        pdf.setFont("helvetica", "italic");
        pdf.setTextColor(156, 163, 175);
        pdf.text("No hay categorías para mostrar", margin, yPosition + 5);
        return yPosition + 15;
      }
    },

    splitTextToLines(pdf, text, maxWidth) {
      const words = text.split(' ');
      const lines = [];
      let currentLine = words[0];

      for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = pdf.getTextWidth(currentLine + " " + word);
        if (width < maxWidth) {
          currentLine += " " + word;
        } else {
          lines.push(currentLine);
          currentLine = word;
        }
      }
      lines.push(currentLine);
      return lines;
    }
  }
};
</script>

<style scoped>
.pdf-export-btn {
  padding: 5px 10px;
  background-color: #890000;
  color: white;
  border: none;
  cursor: pointer;
  border-radius: 6px;
  font-weight: 600;
  transition: all 0.2s;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
}
.pdf-export-btn:hover:not(:disabled) {
  background-color: #a50101;
  transform: translateY(-1px);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}
.pdf-export-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
</style>