<template>
  <div>
    <form @submit.prevent="submitForm" class="mt-2">
      <div class="flex-1 flex-col my-3 px-3 py-2 border-double border border-gray-400 rounded-lg">
        
        <!-- Estado Verificado -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Verificado
          </label>
          <input 
            v-model="form.verified" 
            type="checkbox"
            class="border mt-1 py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
        </div>

        <!-- Username -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Usuario *
          </label>
          <input 
            v-model="form.username" 
            type="text"
            required
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
        </div>

        <!-- Nombre -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Nombre *
          </label>
          <input 
            v-model="form.first_name" 
            type="text"
            required
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
        </div>

        <!-- Apellido -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Apellido
          </label>
          <input 
            v-model="form.last_name" 
            type="text"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
        </div>

        <!-- Email -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Email *
          </label>
          <input 
            v-model="form.email" 
            type="email"
            required
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
        </div>

        <!-- Teléfono -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Teléfono
          </label>
          <input 
            v-model="form.phone" 
            type="tel"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
        </div>

        <!-- Dirección -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Dirección
          </label>
          <textarea 
            v-model="form.address" 
            rows="3"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          ></textarea>
        </div>

        <!-- Código Postal -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Código Postal
          </label>
          <input 
            v-model="form.zipcode" 
            type="text"
            maxlength="10"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
        </div>

        <!-- Contraseña (solo en modo creación) -->
        <div class="flex flex-row items-center my-3 mx-2" v-if="mode === 'create'">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Contraseña *
          </label>
          <input 
            v-model="form.password" 
            type="password"
            required
            minlength="6"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
        </div>
      </div>

      <!-- Botones de Acción -->
      <div class="flex flex-1 gap-3 mt-10 flex-row-reverse">
        <button 
          type="button" 
          class="inline-flex border border-transparent bg-green-600 rounded-md font-semibold text-xs text-white uppercase px-4 py-2 shadow-sm hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
          :disabled="loading"
          @click="submitForm"
        >
          Salvar
          <span v-if="loading" class="flex items-center ml-2">
            <i class="fa fa-spinner fa-pulse"></i>
          </span>
        </button>
        
        <button 
          type="button" 
          class="inline-flex border border-gray-400 bg-red rounded-md font-semibold text-xs text-white uppercase tracking-widest shadow-sm px-4 py-2
                    hover:text-white 
                    focus:outline-none focus:border-red-300 focus:ring focus:ring-red-200 
                    active:text-gray-800 active:bg-red-50 
                    disabled:opacity-25 transition"
          :disabled="loading"
          @click="cancelForm"
        >
          Cancelar
        </button>
      </div>
    </form>
  </div>
</template>

<script>
import MarketplaceUserService from "@/services/marketplace/marketplace_user.service";
import Swal from 'sweetalert2';

export default {
  props: {
    info: { type: Number, default: null },
    mode: { type: String, default: 'create' }
  },
  
  name: "CrudMarketplaceUser",
  
  data() {
    return {
      loading: false,
      
      form: {
        username: '',
        first_name: '',
        last_name: '',
        email: '',
        address: '',
        phone: '',
        zipcode: '',
        verified: false,
        token: '',
        password: '',
      }
    };
  },
  
  computed: {
    isEditing() {
      return this.mode === 'update';
    }
  },
  
  created() {
    this.initForm();
  },
  
  watch: {
    mode() {
      this.initForm();
    }
  },
  
  methods: {
    initForm() {
      if (this.mode !== 'create' && this.info) {
        MarketplaceUserService.getById(this.info).then(item => {
          if (item) {
            this.form.id = item.id;
            this.form.username = item.username || '';
            this.form.first_name = item.first_name || '';
            this.form.last_name = item.last_name || '';
            this.form.email = item.email || '';
            this.form.address = item.address || '';
            this.form.phone = item.phone || '';
            this.form.zipcode = item.zipcode || '';
            this.form.verified = item.verified ? true : false;
            this.form.token = item.token || '';
            this.form.password = ''; // No mostrar contraseña en edición
          }
        });
      } else {
        this.form = {
          username: '',
          first_name: '',
          last_name: '',
          email: '',
          address: '',
          phone: '',
          zipcode: '',
          verified: false,
          token: '',
          password: '',
        };
      }
    },

    async submitForm() {
      // Validaciones
      if (!this.form.username || this.form.username.trim() === '') {
        Swal.fire('Error', 'El nombre de usuario es requerido', 'error');
        return;
      }

      if (!this.form.first_name || this.form.first_name.trim() === '') {
        Swal.fire('Error', 'El nombre es requerido', 'error');
        return;
      }

      if (!this.form.email || this.form.email.trim() === '') {
        Swal.fire('Error', 'El email es requerido', 'error');
        return;
      }

      // Validar formato de email
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(this.form.email)) {
        Swal.fire('Error', 'El formato del email no es válido', 'error');
        return;
      }

      // Validar contraseña en modo creación
      if (this.mode === 'create' && (!this.form.password || this.form.password.length < 6)) {
        Swal.fire('Error', 'La contraseña debe tener al menos 6 caracteres', 'error');
        return;
      }

      // Loading
      Swal.fire({
        title: 'Procesando...',
        html: 'Guardando información',
        allowOutsideClick: false,
        allowEscapeKey: false,
        showConfirmButton: false,
        willOpen: () => Swal.showLoading()
      });

      this.loading = true;

      try {
        // Preparar datos
        const data = {
          username: this.form.username,
          first_name: this.form.first_name,
          last_name: this.form.last_name,
          email: this.form.email,
          address: this.form.address,
          phone: this.form.phone,
          zipcode: this.form.zipcode,
          verified: this.form.verified ? 1 : 0,
          token: this.form.token,
        };

        // Agregar contraseña solo en modo creación
        if (this.mode === 'create') {
          data.password = this.form.password;
        }

        if (this.form.id) {
          data.id = this.form.id;
        }

        const res = await MarketplaceUserService.addUpdMarketplaceUser(
          data, 
          this.mode === 'create'
        );

        Swal.close();

        if (res) {
          await Swal.fire({
            icon: 'success',
            title: '¡Éxito!',
            text: this.mode === 'create' ? 'Creado correctamente' : 'Actualizado correctamente',
            timer: 2000,
            showConfirmButton: false
          });

          this.$emit('actionInfo', { type: 'success' });
        } else {
          throw new Error('Error del servidor');
        }
      } catch (error) {
        Swal.close();
        Swal.fire('Error', 'Error al guardar', 'error');
      } finally {
        this.loading = false;
      }
    },

    cancelForm() {
      Swal.fire({
        title: '¿Estás seguro?',
        text: 'Los cambios no guardados se perderán',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#3085d6',
        cancelButtonColor: '#d33',
        confirmButtonText: 'Sí, cancelar',
        cancelButtonText: 'No, continuar'
      }).then((result) => {
        if (result.isConfirmed) {
          this.$emit('actionInfo', { type: 'cancel' });
        }
      });
    }
  }
};
</script>

