import Authorization from "../user/auth.service";

const base_url = "marketplace-warehouse-coverage";

const MarketplaceWarehouseCoverageService = {
  // ============ LISTADOS ============
  
  async getList(filters = {}) {
    try {
      const search_data = { auth: "bearer", ...filters };
      const { status, data } = await Authorization.checkLogin(
        `/${base_url}`,
        search_data,
        "post"
      );
      if (status === 200) {
        const list = [];
        for (let item of data) {
          list.push(this.transformItem(item));
        }
        return list;
      }
    } catch (e) {
      console.error(e);
      return [];
    }
  },

  getSimpleList() {
    return this.getList().then(list => {
      return list.map(l => ({
        value: l.id,
        text: `${l.warehouse_name} - ${l.province_name}${l.city_name ? ' / ' + l.city_name : ''}`
      }));
    });
  },

  async getById(id) {
    try {
      const { status, data } = await Authorization.checkLogin(
        `/${base_url}/${id}`,
        { auth: "bearer" }
      );
      if (status === 200) return data;
    } catch (e) {
      console.error(e.response);
    }
  },

  // ============ CRUD ============

  async addUpdMarketplaceWarehouseCoverage(form_data, is_new = true, hasImage = false) {
    try {
      form_data.auth = "bearer";
      const url = is_new
        ? `/${base_url}/create`
        : `/${base_url}/upd`;
      const method = is_new ? "post" : "put";

      const { status, data } = hasImage
        ? await Authorization.checkLoginImage(url, form_data.form, method)
        : await Authorization.checkLogin(url, form_data, method);

      if (status === 200) return {
        status: true,
        data
      };
    } catch (e) {
      return {
        status: false,
        message: e.message 
      };
    }
    // console.error('error', data);
    return {
      status: false,
    };
  },

  async delete(ids) {
    const delete_data = { auth: "bearer", ids };
    try {
      const { status, data } = await Authorization.checkLogin(
        `/${base_url}/delete`,
        delete_data,
        "post"
      );
      if (status === 200) {
        return this.getList();
      }
    } catch (e) {
      console.error(e.response);
    }
  },

  // ============ FAST UPDATE ============

  async fastUpdate(id, field, value) {
    try {
      let column = field;
      
      const form_data = { auth: "bearer", [column]: value };
      const { status, data } = await Authorization.checkLogin(
        `/${base_url}/fast-upd/${id}`,
        form_data,
        "put"
      );
      if (status === 200) return data;
    } catch (e) {
      console.error(e.response);
    }
    return false;
  },

  // ============ BÚSQUEDA Y EXPORTACIÓN ============

  async search(filters = {}) {
    try {
      const search_data = { auth: "bearer", ...filters };
      const { status, data } = await Authorization.checkLogin(
        `/${base_url}/search-backend`,
        search_data,
        "post"
      );
      if (status === 200) {
        const list = [];
        for (let item of data) {
          list.push(this.transformItem(item));
        }
        return list;
      }
    } catch (e) {
      console.error(e.response);
      return [];
    }
  },

  async searchAndExport(filters = {}, limit = null, offset = 0) {
    try {
      const search_data = { auth: "bearer", ...filters };
      if (limit !== null) search_data.limit = limit;
      if (offset > 0) search_data.offset = offset;

      const { status, data } = await Authorization.checkLogin(
        `/${base_url}`,
        search_data,
        "post"
      );
      if (status === 200) {
        const list = [];
        for (let item of data) {
          list.push({
            ...this.transformItem(item),
            created_at: item.created_at,
            updated_at: item.updated_at,
          });
        }
        return list;
      }
    } catch (e) {
      console.error(e.response);
      return [];
    }
  },

  async getCount(filters = {}) {
    try {
      const search_data = { 
        auth: "bearer", 
        ...filters,
        count_only: true 
      };
      const { status, data } = await Authorization.checkLogin(
        `/${base_url}`,
        search_data,
        "post"
      );
      if (status === 200) return data.count || data;
      return 0;
    } catch (e) {
      console.error(e.response);
      return 0;
    }
  },

  // ============ TRANSFORMACIÓN ============

  transformItem(item) {
    return {
      id: item.id,
      // warehouse_id: item.warehouse_id,
      Almacen: item.warehouse_name || '',
      // province_id: item.province_id,
      Provincia: item.province_name || '',
      // city_id: item.city_id,
      Ciudad: item.city_name || '-General-',
      ['Días']: item.delivery_days || 1,
      ['Delivery']: item.delivery_cost_factor || 0,
      Prioridad: item.priority || 1,
      Activo: item.active ? true : false,
    };
  }
};

export default MarketplaceWarehouseCoverageService;
