<template>
  <div>
    <form @submit.prevent="submitForm" class="mt-2">
      <div class="flex-1 flex-col my-3 px-3 py-2 border-double border border-gray-400 rounded-lg">
        
        <!-- Estado Activo -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Activo
          </label>
          <input 
            v-model="form.active" 
            type="checkbox"
            class="border mt-1 py-2 px-3 border-gray-400 bg-white rounded-md"
          >
          <span class="ml-2 text-xs text-gray-500">¿Cobertura activa?</span>
        </div>
        
        <!-- Almacén (requerido) -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Almacén *
          </label>
          <select 
            v-model="form.warehouse_id"
            required
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
            <option value="">Seleccione almacén</option>
            <option v-for="warehouse in warehouses" :key="warehouse.value" :value="warehouse.value">
              {{ warehouse.text }}
            </option>
          </select>
        </div>

        <!-- Provincia (requerido) -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Provincia *
          </label>
          <select 
            v-model="form.province_id"
            @change="onProvinceChange"
            required
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
            <option value="">Seleccione provincia</option>
            <option v-for="province in provinces" :key="province.value" :value="province.value">
              {{ province.text }}
            </option>
          </select>
        </div>

        <!-- Ciudad (opcional) -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Ciudad
          </label>
          <select 
            v-model="form.city_id"
            :disabled="!form.province_id"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
            <option value="">Toda la provincia</option>
            <option v-for="city in filteredCities" :key="city.value" :value="city.value">
              {{ city.text }}
            </option>
          </select>
          <span class="ml-2 text-xs text-gray-500">Dejar vacío para cubrir toda la provincia</span>
        </div>

        <!-- Prioridad -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Prioridad
          </label>
          <input 
            v-model="form.priority" 
            type="number"
            min="1"
            max="100"
            placeholder="Orden de preferencia (menor = mayor prioridad)"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
          <span class="ml-2 text-xs text-gray-500">Menor número = mayor prioridad</span>
        </div>

        <!-- Días de entrega -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Días Entrega
          </label>
          <input 
            v-model="form.delivery_days" 
            type="number"
            min="0"
            max="30"
            placeholder="Días estimados de entrega"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
          <span class="ml-2 text-xs text-gray-500">Días desde este almacén a la zona</span>
        </div>

        <!-- Factor de costo de envío -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Costo de envío
          </label>
          <input 
            v-model="form.delivery_cost_factor" 
            type="number"
            step="0.01"
            min="0"
            max="999.99"
            placeholder="Factor multiplicador de costo"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
          <span class="ml-2 text-xs text-gray-500">Costo envío desde el almacén</span>
        </div>

        <!-- Notas -->
        <div class="flex flex-row items-start my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32 pt-2">
            Notas
          </label>
          <textarea 
            v-model="form.notes" 
            rows="2"
            placeholder="Notas sobre esta cobertura"
            maxlength="255"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          ></textarea>
        </div>
      </div>

      <!-- Botones de Acción -->
      <div class="flex flex-1 gap-3 mt-10 flex-row-reverse">
        <button 
          type="button" 
          class="inline-flex border border-transparent bg-green-600 rounded-md font-semibold text-xs text-white uppercase px-4 py-2"
          :disabled="loading"
          @click="submitForm"
        >
          Salvar
          <span v-if="loading" class="flex items-center ml-2">
            <i class="fa fa-spinner fa-pulse"></i>
          </span>
        </button>
        
        <button 
          type="button" 
          class="inline-flex border border-gray-400 bg-red rounded-md font-semibold text-xs text-white uppercase tracking-widest shadow-sm px-4 py-2
                    hover:text-white 
                    focus:outline-none focus:border-red-300 focus:ring focus:ring-red-200 
                    active:text-gray-800 active:bg-red-50 
                    disabled:opacity-25 transition"
          :disabled="loading"
          @click="cancelForm"
        >
          Cancelar
        </button>
      </div>
    </form>
  </div>
</template>

<script>
import MarketplaceWarehouseCoverageService from "@/services/marketplace/marketplace_warehouse_coverage.service";
import MarketplaceWarehouseService from "@/services/marketplace/marketplace_warehouse.service";
import MarketplaceProvinceService from "@/services/marketplace/marketplace_province.service";
import MarketplaceCityService from "@/services/marketplace/marketplace_city.service";
import Swal from 'sweetalert2';

export default {
  props: {
    info: { type: Number, default: null },
    mode: { type: String, default: 'create' }
  },
  
  name: "CrudMarketplaceWarehouseCoverage",
  
  data() {
    return {
      loading: false,
      warehouses: [],
      provinces: [],
      cities: [],
      
      form: {
        warehouse_id: '',
        province_id: '',
        city_id: '',
        priority: 1,
        delivery_days: 1,
        delivery_cost_factor: 0,
        active: true,
        notes: '',
      }
    };
  },
  
  computed: {
    isEditing() {
      return this.mode === 'update';
    },
    
    filteredCities() {
      if (!this.form.province_id) return [];
      const provinceId = parseInt(this.form.province_id);
      const filtered = this.cities.filter(city => {
        return city.province_id === provinceId;
      });
      return filtered;
    }
  },
  
  async created() {
    await Promise.all([
      this.loadWarehouses(),
      this.loadProvinces(),
      this.loadCities()
    ]);
    this.initForm();
  },
  
  watch: {
    mode() {
      this.initForm();
    }
  },
  
  methods: {
    async loadWarehouses() {
      this.warehouses = await MarketplaceWarehouseService.getSimpleList();
    },
    
    async loadProvinces() {
      this.provinces = await MarketplaceProvinceService.getSimpleList({filters: [{
        field: 'active',
        value: 1
      }]});
    },
    
    async loadCities() {
      this.cities = await MarketplaceCityService.getSimpleList();
    },
    
    onProvinceChange() {
      this.form.city_id = '';
    },
    
    initForm() {
      if (this.mode !== 'create' && this.info) {
        MarketplaceWarehouseCoverageService.getById(this.info).then(item => {
          if (item) {
            this.form = {
              id: item.id,
              warehouse_id: item.warehouse_id || '',
              province_id: item.province_id || '',
              city_id: item.city_id || '',
              priority: item.priority || 1,
              delivery_days: item.delivery_days || 1,
              delivery_cost_factor: item.delivery_cost_factor || 0,
              active: item.active ? true : false,
              notes: item.notes || '',
            };
          }
        });
      } else {
        this.form = {
          warehouse_id: '',
          province_id: '',
          city_id: '',
          priority: 1,
          delivery_days: 1,
          delivery_cost_factor: 0,
          active: true,
          notes: '',
        };
      }
    },

    async submitForm() {
      // Validaciones
      if (!this.form.warehouse_id) {
        Swal.fire({
          icon: 'warning',
          title: 'Campo requerido',
          text: 'Debe seleccionar un almacén',
          confirmButtonText: 'Entendido'
        });
        return;
      }

      if (!this.form.province_id) {
        Swal.fire({
          icon: 'warning',
          title: 'Campo requerido',
          text: 'Debe seleccionar una provincia',
          confirmButtonText: 'Entendido'
        });
        return;
      }

      // Loading
      Swal.fire({
        title: 'Procesando...',
        html: 'Guardando cobertura de almacén',
        allowOutsideClick: false,
        allowEscapeKey: false,
        showConfirmButton: false,
        willOpen: () => Swal.showLoading()
      });

      this.loading = true;

      try {
        const data = {
          warehouse_id: this.form.warehouse_id,
          province_id: this.form.province_id,
          city_id: this.form.city_id || null,
          priority: parseInt(this.form.priority) || 1,
          delivery_days: parseInt(this.form.delivery_days) || 1,
          delivery_cost_factor: parseFloat(this.form.delivery_cost_factor) || 0,
          active: this.form.active ? 1 : 0,
          notes: this.form.notes?.trim() || '',
        };

        if(this.form.id) data.id = this.form.id;

        const res = await MarketplaceWarehouseCoverageService.addUpdMarketplaceWarehouseCoverage(
          data,
          this.mode === 'create',
          false
        );

        Swal.close();

        if (res.status) {
          await Swal.fire({
            icon: 'success',
            title: '¡Éxito!',
            text: this.mode === 'create' ? 'Cobertura creada correctamente' : 'Cobertura actualizada correctamente',
            timer: 2000,
            showConfirmButton: false
          });

          this.$emit('actionInfo', { type: 'success' });
        } else {
          throw new Error(res.message);
        }
      } catch (error) {
        Swal.close();
        Swal.fire({
          icon: 'error',
          title: 'Error',
          text: 'Error al guardar la cobertura: ' + error.message,
          confirmButtonText: 'Cerrar'
        });
      } finally {
        this.loading = false;
      }
    },

    cancelForm() {
      Swal.fire({
        title: '¿Estás seguro?',
        text: 'Los cambios no guardados se perderán',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#3085d6',
        cancelButtonColor: '#d33',
        confirmButtonText: 'Sí, cancelar',
        cancelButtonText: 'No, continuar'
      }).then((result) => {
        if (result.isConfirmed) {
          this.$emit('actionInfo', { type: 'cancel' });
        }
      });
    }
  }
};
</script>

