<template>
  <div>
    <form @submit.prevent="submitForm" class="mt-2">
      <div class="flex-1 flex-col my-3 px-3 py-2 border-double border border-gray-400 rounded-lg">
        
        <!-- Estado Activo -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Activo
          </label>
          <input 
            v-model="form.active" 
            type="checkbox"
            class="border mt-1 py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
        </div>

        <!-- Provincia -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Provincia *
          </label>
          <model-select 
            :options="provincesList"      
            v-model="form.province_name"              
            placeholder="Seleccione una provincia*"
            required                           
            class="flex-1 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
            focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
          </model-select>
        </div>

        <!-- Ciudad -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Ciudad *
          </label>
          <model-select 
            :options="citiesList"      
            v-model="form.city_name"              
            placeholder="Seleccione una ciudad*"
            required                           
            class="flex-1 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
            focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
          </model-select>
        </div>

        <!-- Email Usuario -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Email Usuario *
          </label>
          <model-select 
            :options="usersList"      
            v-model="form.user_email"              
            placeholder="Seleccione un usuario*"
            required                           
            class="flex-1 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
            focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
          </model-select>
        </div>

        <!-- Costo -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Costo
          </label>
          <input 
            v-model="form.costo" 
            type="number"
            step="0.01"
            min="0"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
        </div>

        <!-- Descripción -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Descripción
          </label>
          <textarea 
            v-model="form.description" 
            rows="3"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          ></textarea>
        </div>
      </div>

      <!-- Botones de Acción -->
      <div class="flex flex-1 gap-3 mt-10 flex-row-reverse">
        <button 
          type="button" 
          class="inline-flex border border-transparent bg-green-600 rounded-md font-semibold text-xs text-white uppercase px-4 py-2 shadow-sm hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
          :disabled="loading"
          @click="submitForm"
        >
          Salvar
          <span v-if="loading" class="flex items-center ml-2">
            <i class="fa fa-spinner fa-pulse"></i>
          </span>
        </button>
        
        <button 
          type="button" 
          class="inline-flex border border-gray-400 bg-red rounded-md font-semibold text-xs text-white uppercase tracking-widest shadow-sm px-4 py-2
                    hover:text-white 
                    focus:outline-none focus:border-red-300 focus:ring focus:ring-red-200 
                    active:text-gray-800 active:bg-red-50 
                    disabled:opacity-25 transition"
          :disabled="loading"
          @click="cancelForm"
        >
          Cancelar
        </button>
      </div>
    </form>
  </div>
</template>

<script>
import MarketplaceUserDeliveryService from "@/services/marketplace/marketplace_user_delivery.service";
import MarketplaceUserService from "@/services/marketplace/marketplace_user.service";
import MarketplaceProvinceService from "@/services/marketplace/marketplace_province.service";
import MarketplaceCityService from "@/services/marketplace/marketplace_city.service";
import { ModelSelect } from 'vue-search-select'
import 'vue-search-select/dist/VueSearchSelect.css'
import Swal from 'sweetalert2';

export default {
  props: {
    info: { type: Number, default: null },
    mode: { type: String, default: 'create' }
  },
  
  name: "CrudMarketplaceUserDelivery",
  
  components: {
    ModelSelect
  },
  
  data() {
    return {
      loading: false,
      usersList: [],
      provincesList: [],
      citiesList: [],
      
      form: {
        user_email: {
          text: '',
          value: ''
        },
        province_name: {
          text: '',
          value: ''
        },
        city_name: {
          text: '',
          value: ''
        },
        costo: 0,
        description: '',
        active: true,
      }
    };
  },
  
  computed: {
    isEditing() {
      return this.mode === 'update';
    }
  },
  
  created() {
    this.loadLists();
    this.initForm();
  },
  
  watch: {
    mode() {
      this.initForm();
    }
  },
  
  methods: {
    initForm() {      
      if (this.mode !== 'create' && this.info) {
        MarketplaceUserDeliveryService.getById(this.info).then(item => {          
          console.log(item)
          if (item) {
            this.form.id = item.id;
            this.form.user_email = {
              text: item.user_email || '',
              value: item.user_id || ''
            };
            this.form.province_name = {
              text: item.province_name || '',
              value: item.province_id || ''
            };
            this.form.city_name = {
              text: item.city_name || '',
              value: item.city_id || ''
            };
            this.form.costo = item.cost || 0;
            this.form.description = item.description || '';
            this.form.active = item.active ? true : false;
          }
        });
      } else {
        this.form = {
          user_email: {
            text: '',
            value: ''
          },
          province_name: {
            text: '',
            value: ''
          },
          city_name: {
            text: '',
            value: ''
          },
          costo: 0,
          active: true,
        };
      }
    },

    async loadLists() {
      try {
        const users = await MarketplaceUserService.getSimpleList();
        const provinces = await MarketplaceProvinceService.getSimpleList();
        const cities = await MarketplaceCityService.getSimpleList();
        this.usersList = users || [];
        this.provincesList = provinces || [];
        this.citiesList = cities || [];
      } catch (error) {
        console.error('Error loading lists:', error);
        Swal.fire('Error', 'Error al cargar las listas', 'error');
      }
    },

    async submitForm() {
      // Validaciones
      if (!this.form.user_email.value || this.form.user_email.value === '') {
        Swal.fire('Error', 'El usuario es requerido', 'error');
        return;
      }

      if (!this.form.province_name.value || this.form.province_name.value === '') {
        Swal.fire('Error', 'La provincia es requerida', 'error');
        return;
      }

      if (!this.form.city_name.value || this.form.city_name.value === '') {
        Swal.fire('Error', 'La ciudad es requerida', 'error');
        return;
      }

      // Loading
      Swal.fire({
        title: 'Procesando...',
        html: 'Guardando información',
        allowOutsideClick: false,
        allowEscapeKey: false,
        showConfirmButton: false,
        willOpen: () => Swal.showLoading()
      });

      this.loading = true;

      try {
        // Preparar datos
        const data = {
          user_id: this.form.user_email.value,
          province_id: this.form.province_name.value,
          city_id: this.form.city_name.value,
          cost: this.form.costo,
          description: this.form.description,
          active: this.form.active ? 1 : 0,
        };

        if (this.form.id) {
          data.id = this.form.id;
        }

        const res = await MarketplaceUserDeliveryService.addUpdMarketplaceUserDelivery(data);

        Swal.close();

        if (res) {
          await Swal.fire({
            icon: 'success',
            title: '¡Éxito!',
            text: this.mode === 'create' ? 'Creado correctamente' : 'Actualizado correctamente',
            timer: 2000,
            showConfirmButton: false
          });

          this.$emit('actionInfo', { type: 'success' });
        } else {
          throw new Error('Error del servidor');
        }
      } catch (error) {
        Swal.close();
        Swal.fire('Error', 'Error al guardar', 'error');
      } finally {
        this.loading = false;
      }
    },

    cancelForm() {
      this.$emit('actionInfo', { type: 'cancel' });
    }
  }
};
</script>

