<template>
  <div>
    <form @submit.prevent="submitForm" class="mt-2">
      <div class="flex-1 flex-col my-3 px-3 py-2 border-double border border-gray-400 rounded-lg">
        
        <!-- Estado Activo -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Activo
          </label>
          <input 
            v-model="form.active" 
            type="checkbox"
            class="border mt-1 py-2 px-3 border-gray-400 bg-white rounded-md"
          >
        </div>

        <!-- Almacén por defecto -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Por Defecto
          </label>
          <input 
            v-model="form.is_default" 
            type="checkbox"
            class="border mt-1 py-2 px-3 border-gray-400 bg-white rounded-md"
          >
          <span class="ml-2 text-xs text-gray-500">Marcar como almacén principal del sistema</span>
        </div>

        <!-- Nombre (requerido) -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Nombre *
          </label>
          <input 
            v-model="form.name" 
            type="text"
            required
            placeholder="Nombre identificativo del almacén"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
        </div>

        <!-- Código -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Código
          </label>
          <input 
            v-model="form.code" 
            type="text"
            placeholder="Código interno opcional"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
        </div>

        <!-- Tipo -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Tipo
          </label>
          <select 
            v-model="form.type"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
            <option value="central">Central</option>
            <option value="regional">Regional</option>
            <option value="local">Local</option>
          </select>
        </div>

        <!-- Capacidad -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Capacidad
          </label>
          <input 
            v-model="form.capacity" 
            type="number"
            min="0"
            placeholder="Capacidad en unidades"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
        </div>

        <!-- Provincia -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Provincia
          </label>
          <select 
            v-model="form.province_id"
            @change="onProvinceChange"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
            <option value="">Seleccione provincia</option>
            <option v-for="province in provinces" :key="province.value" :value="province.value">
              {{ province.text }}
            </option>
          </select>
        </div>

        <!-- Ciudad -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Ciudad
          </label>
          <select 
            v-model="form.city_id"
            :disabled="!form.province_id"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
            <option value="">Seleccione ciudad</option>
            <option v-for="city in cities" :key="city.value" :value="city.value">
              {{ city.text }}
            </option>
          </select>
        </div>

        <!-- Dirección -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Dirección
          </label>
          <input 
            v-model="form.address" 
            type="text"
            placeholder="Dirección física completa"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
        </div>

        <!-- Teléfono -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Teléfono
          </label>
          <input 
            v-model="form.phone" 
            type="text"
            placeholder="Teléfono de contacto"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
        </div>

        <!-- Email -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Email
          </label>
          <input 
            v-model="form.email" 
            type="email"
            placeholder="Correo electrónico de contacto"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
        </div>

        <!-- Encargado -->
        <div class="flex flex-row items-center my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
            Encargado
          </label>
          <input 
            v-model="form.manager_name" 
            type="text"
            placeholder="Nombre del encargado"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          >
        </div>

        <!-- Notas -->
        <div class="flex flex-row items-start my-3 mx-2">
          <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32 pt-2">
            Notas
          </label>
          <textarea 
            v-model="form.notes" 
            rows="3"
            placeholder="Notas internas"
            class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md"
          ></textarea>
        </div>
      </div>

      <!-- Botones de Acción -->
      <div class="flex flex-1 gap-3 mt-10 flex-row-reverse">
        <button 
          type="button" 
          class="inline-flex border border-transparent bg-green-600 rounded-md font-semibold text-xs text-white uppercase px-4 py-2"
          :disabled="loading"
          @click="submitForm"
        >
          Salvar
          <span v-if="loading" class="flex items-center ml-2">
            <i class="fa fa-spinner fa-pulse"></i>
          </span>
        </button>
        
        <button 
          type="button" 
          class="inline-flex border border-gray-400 bg-red rounded-md font-semibold text-xs text-white uppercase tracking-widest shadow-sm px-4 py-2
                    hover:text-white 
                    focus:outline-none focus:border-red-300 focus:ring focus:ring-red-200 
                    active:text-gray-800 active:bg-red-50 
                    disabled:opacity-25 transition"
          :disabled="loading"
          @click="cancelForm"
        >
          Cancelar
        </button>
      </div>
    </form>
  </div>
</template>

<script>
import MarketplaceWarehouseService from "@/services/marketplace/marketplace_warehouse.service";
import MarketplaceProvinceService from "@/services/marketplace/marketplace_province.service";
import MarketplaceCityService from "@/services/marketplace/marketplace_city.service";
import Swal from 'sweetalert2';

export default {
  props: {
    info: { type: Number, default: null },
    mode: { type: String, default: 'create' }
  },
  
  name: "CrudMarketplaceWarehouse",
  
  data() {
    return {
      loading: false,
      provinces: [],
      cities: [],
      
      form: {
        name: '',
        code: '',
        type: 'local',
        capacity: 0,
        province_id: '',
        city_id: '',
        address: '',
        phone: '',
        email: '',
        manager_name: '',
        notes: '',
        active: true,
        is_default: false,
      }
    };
  },
  
  computed: {
    isEditing() {
      return this.mode === 'update';
    }
  },
  
  created() {
    this.loadProvinces();
    this.initForm();
  },
  
  watch: {
    mode() {
      this.initForm();
    }
  },
  
  methods: {
    async loadProvinces() {
      this.provinces = await MarketplaceProvinceService.getSimpleList();
    },
    
    async loadCities(provinceId) {
      if (!provinceId) {
        this.cities = [];
        return;
      }
      // Si el servicio de city tiene método para filtrar por provincia
      const allCities = await MarketplaceCityService.getSimpleList();
      // Aquí podrías filtrar si el servicio lo permite
      this.cities = allCities;
    },
    
    onProvinceChange() {
      this.form.city_id = '';
      this.loadCities(this.form.province_id);
    },
    
    initForm() {
      console.log(this.info);
      if (this.mode !== 'create' && this.info) {
        MarketplaceWarehouseService.getById(this.info).then(item => {
          if (item) {
            this.form = {
              id: item.id,
              name: item.name || '',
              code: item.code || '',
              type: item.type || 'local',
              capacity: item.capacity || 0,
              province_id: item.province_id || '',
              city_id: item.city_id || '',
              address: item.address || '',
              phone: item.phone || '',
              email: item.email || '',
              manager_name: item.manager_name || '',
              notes: item.notes || '',
              active: item.active ? true : false,
              is_default: item.is_default ? true : false,
            };
            
            
            if (this.form.province_id) {
              this.loadCities(this.form.province_id);
            }
          }
        });
      } 
    },

    async submitForm() {
      // Validaciones
      if (!this.form.name || this.form.name.trim() === '') {
        Swal.fire({
          icon: 'warning',
          title: 'Campo requerido',
          text: 'El nombre del almacén es obligatorio',
          confirmButtonText: 'Entendido'
        });
        return;
      }

      // Loading
      Swal.fire({
        title: 'Procesando...',
        html: 'Guardando información del almacén',
        allowOutsideClick: false,
        allowEscapeKey: false,
        showConfirmButton: false,
        willOpen: () => Swal.showLoading()
      });

      this.loading = true;

      try {
        const data = {
          name: this.form.name.trim(),
          code: this.form.code?.trim() || '',
          type: this.form.type,
          capacity: parseInt(this.form.capacity) || 0,
          province_id: this.form.province_id || null,
          city_id: this.form.city_id || null,
          address: this.form.address?.trim() || '',
          phone: this.form.phone?.trim() || '',
          email: this.form.email?.trim() || '',
          manager_name: this.form.manager_name?.trim() || '',
          notes: this.form.notes?.trim() || '',
          active: this.form.active ? 1 : 0,
          is_default: this.form.is_default ? 1 : 0,
        };

        const res = await MarketplaceWarehouseService.addUpdMarketplaceWarehouse(
          { form: data, id: this.form.id },
          this.mode === 'create',
          false
        );

        Swal.close();

        if (res) {
          await Swal.fire({
            icon: 'success',
            title: '¡Éxito!',
            text: this.mode === 'create' ? 'Almacén creado correctamente' : 'Almacén actualizado correctamente',
            timer: 2000,
            showConfirmButton: false
          });

          this.$emit('actionInfo', { type: 'success' });
        } else {
          throw new Error('Error del servidor');
        }
      } catch (error) {
        Swal.close();
        Swal.fire({
          icon: 'error',
          title: 'Error',
          text: 'Error al guardar el almacén',
          confirmButtonText: 'Cerrar'
        });
      } finally {
        this.loading = false;
      }
    },

    cancelForm() {
      Swal.fire({
        title: '¿Estás seguro?',
        text: 'Los cambios no guardados se perderán',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#3085d6',
        cancelButtonColor: '#d33',
        confirmButtonText: 'Sí, cancelar',
        cancelButtonText: 'No, continuar'
      }).then((result) => {
        if (result.isConfirmed) {
          this.$emit('actionInfo', { type: 'cancel' });
        }
      });
    }
  }
};
</script>

